<script setup>
import { computed, ref, watch } from 'vue'
import { call, downloadFile } from './api.js'
import { api } from '../api.js'
import ReportPreview from './ReportPreview.vue'
import ReportReview from './ReportReview.vue'
import ToastNotice from './ToastNotice.vue'
const props = defineProps({ taskId: String })
const rows = ref([]), query = ref(''), filter = ref('all'), active = ref(null), busy = ref(false), aiLoading = ref(false), error = ref(''), notice = ref(''), mode = ref('review')
const returnRow = ref(null), returnReason = ref('')
let loadGeneration = 0
const comparison = ref(null), otherId = ref(''), originals = ref(false), comparisonOpen = ref(false)
const status = r => !r ? '未提交' : r.returned ? '已退回' : r.finalScore != null ? '已批改' : r.reviewStatus === 'reviewing' ? '批改中' : '待批改'
const stamp = v => v ? new Date(v).toLocaleString('zh-CN', { hour12: false }) : '—'
const filtered = computed(() => rows.value.filter(r => `${r.name} ${r.sid} ${r.cls || ''} ${r.groupName}`.includes(query.value.trim()) && (filter.value === 'all' || status(r.latest) === filter.value)))
const selected = computed(() => active.value?.latest)
const candidates = computed(() => rows.value.filter(r => r.latest && r.sid !== active.value?.sid))
async function perform(fn, success = '') { if (busy.value) return; busy.value = true; error.value = ''; notice.value = ''; try { await fn(); notice.value = success } catch (e) { error.value = e.message } finally { busy.value = false } }
function clearToast() { if (error.value) error.value = ''; else notice.value = '' }
async function load() { const generation = ++loadGeneration; const result = await call(`/report-desk?taskId=${encodeURIComponent(props.taskId)}`); if (generation !== loadGeneration) return; rows.value = result; if (active.value) active.value = rows.value.find(r => r.runId === active.value.runId && r.sid === active.value.sid) || null }
watch(() => props.taskId, () => { active.value = null; comparisonOpen.value = false; load().catch(e => { error.value = e.message }) }, { immediate: true })
async function open(row, nextMode = 'review') {
  if (!row.latest) return
  active.value = row
  comparisonOpen.value = false
  mode.value = nextMode
  if (nextMode === 'review') await call(`/report-desk/${row.latest.id}/begin`, 'POST')
  await load()
}
async function review(action, values) { const run = await call(`/runs/${active.value.runId}`); await call(`/runs/${run.id}/reports/${selected.value.id}/review`, 'POST', { ...values, action, revision: run.revision }); await load() }
async function ai() { const run = await call(`/runs/${active.value.runId}`); await call(`/runs/${run.id}/ai/${selected.value.id}`, 'POST', { revision: run.revision }); await load() }
async function generateAi() { aiLoading.value = true; try { await ai() } finally { aiLoading.value = false } }
async function compare() { comparison.value = null; if (otherId.value) comparison.value = await call(`/report-desk/${selected.value.id}/compare?otherId=${encodeURIComponent(otherId.value)}`) }
async function check() { await call(`/report-desk/${selected.value.id}/similarity`, 'POST'); await load(); otherId.value = [...(selected.value.similarity?.matches || [])].sort((a,b) => (b.percent || 0) - (a.percent || 0))[0]?.reportId || candidates.value[0]?.latest.id || ''; comparisonOpen.value = true; await compare() }
async function returnFromList() { const row = returnRow.value; const run = await call(`/runs/${row.runId}`); await call(`/runs/${row.runId}/reports/${row.latest.id}/review`, 'POST', { action: 'return', comment: returnReason.value, revision: run.revision }); returnRow.value = null; returnReason.value = ''; await load() }
async function gradedFile(row = active.value) { const report = row === active.value ? selected.value : row.latest; const response = await fetch(`/api/workflow/report-desk/${report.id}/graded-file`, { headers: { Authorization: `Bearer ${api.getToken()}` } }); if (!response.ok) throw new Error('批阅记录下载失败'); const url = URL.createObjectURL(await response.blob()); const a = document.createElement('a'); a.href = url; a.download = `${row.name}-批阅记录.docx`; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
function fragments(side) { const text = comparison.value?.[`${side}Text`] || ''; const ranges = (comparison.value?.segments || []).map((s,i) => ({ start: s[`${side}Start`], end: s[`${side}End`], index: i })).sort((a,b) => a.start-b.start); const out = []; let cursor = 0; for (const r of ranges) { if (r.start < cursor) continue; out.push({ text: text.slice(cursor, r.start) }); out.push({ text: text.slice(r.start,r.end), index: r.index }); cursor = r.end } out.push({ text: text.slice(cursor) }); return out }
function focusSegment(i) { originals.value = false; setTimeout(() => ['left','right'].forEach(side => document.getElementById(`match-${side}-${i}`)?.scrollIntoView({ block: 'center', behavior: 'smooth' })), 0) }
</script>
<template>
  <section class="report-desk">
    <ToastNotice :message="error || notice" :type="error ? 'error' : 'success'" @close="clearToast" />
    <div v-if="returnRow" class="desk-modal" role="dialog" aria-modal="true" aria-label="退回报告"><form @submit.prevent="perform(returnFromList, '报告已退回')"><h3>退回 {{ returnRow.name }} 的报告</h3><label>退回理由<textarea v-model="returnReason" required rows="4" autofocus /></label><div class="wf-actions"><button class="btn btn-primary" :disabled="busy || !returnReason.trim()">确认退回</button><button type="button" class="btn btn-ghost" :disabled="busy" @click="returnRow = null">取消</button></div></form></div><header class="desk-head"><h2>{{ comparisonOpen ? '查重对比' : active ? (mode === 'similarity' ? '实验报告查重' : '批改实验报告') : '实验报告列表' }}</h2><div class="wf-actions"><button v-if="active" class="btn btn-ghost" @click="comparisonOpen ? comparisonOpen = false : active = null">返回{{ comparisonOpen ? '查重' : '列表' }}</button><button class="btn btn-ghost" :disabled="busy" @click="perform(load, '已刷新')">刷新</button></div></header>
    <template v-if="!active"><div class="desk-tools"><input v-model="query" type="search" placeholder="姓名 / 学号 / 班级 / 小组" aria-label="搜索学生"><select v-model="filter" aria-label="报告状态"><option value="all">全部状态</option><option>未提交</option><option>待批改</option><option>批改中</option><option>已批改</option><option>已退回</option></select><span>{{ filtered.length }} 条记录</span></div>
      <div class="desk-table"><table><thead><tr><th>学生</th><th>班级 / 小组</th><th>实验次数</th><th>提交时间</th><th>批阅时间</th><th>教师</th><th>成绩</th><th>状态</th><th>相似度</th><th>操作</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.runId + row.sid"><td><b>{{ row.name }}</b><small>{{ row.sid }}</small></td><td>{{ row.cls || '—' }}<small>{{ row.groupName }}</small></td><td>第 {{ row.attempt }} 次</td><td>{{ stamp(row.latest?.submittedAt) }}</td><td>{{ stamp(row.latest?.gradedAt) }}</td><td>{{ row.latest?.gradedBy || '—' }}</td><td>{{ row.latest?.finalScore ?? '—' }}</td><td><span class="desk-status" :class="{'done': status(row.latest) === '已批改'}">{{ status(row.latest) }}</span></td><td><button v-if="row.latest?.similarity?.available" class="wf-text-button" :disabled="busy" @click="perform(async () => { await open(row, 'similarity'); await check() })">{{ row.latest.similarity.maxPercent }}%</button><span v-else>—</span></td><td><div class="wf-actions desk-row-actions"><button class="btn btn-ghost" :disabled="busy || !row.latest" @click="perform(() => downloadFile(row.latest.fileId,row.latest.fileName))">原始报告</button><button class="btn btn-primary" :disabled="busy || !row.latest" @click="perform(() => open(row, 'review'))">批阅</button><button class="btn btn-ghost" :disabled="busy || !row.latest" @click="perform(() => open(row, 'similarity'))">查重</button><button v-if="row.latest?.finalScore != null" class="btn btn-ghost" :disabled="busy" @click="perform(() => gradedFile(row))">批阅记录</button><button v-if="row.latest && !row.latest.returned" class="btn btn-ghost" :disabled="busy" @click="returnRow = row; returnReason = ''">退回</button></div></td></tr><tr v-if="!filtered.length"><td colspan="10">暂无报告记录</td></tr></tbody></table></div>
    </template>
    <template v-else-if="comparisonOpen"><div class="desk-tools"><b>{{ active.name }} · 实验报告</b><label>对比报告<select v-model="otherId" :disabled="busy" @change="perform(compare)"><option value="">选择报告</option><option v-for="r in candidates" :key="r.latest.id" :value="r.latest.id">{{ r.name }} · {{ r.groupName }} · 第 {{ r.attempt }} 次</option></select></label><button class="btn btn-ghost" @click="originals = !originals">{{ originals ? '查看相似片段' : '查看原始报告' }}</button><b v-if="comparison?.available">相似度 {{ comparison.percent }}%</b></div><p v-if="comparison && !comparison.available">{{ comparison.reason }}</p><p v-if="!otherId">暂无可对比报告</p><template v-if="comparison"><div class="desk-segments"><button v-for="(s,i) in comparison.segments" :key="i" @click="focusSegment(i)"><b>{{ s.length }} 字 · 相同片段</b><span>{{ s.text }}</span></button></div><p v-if="comparison.available && !comparison.segments.length">未检出可定位的相同片段</p><div class="desk-compare"><article v-for="side in ['left','right']" :key="side"><h3>{{ side === 'left' ? '当前报告' : '对比报告' }} · {{ comparison[side].sid }}</h3><button class="wf-text-button" @click="perform(() => downloadFile(comparison[side].fileId, comparison[side].fileName))">下载原始文件</button><ReportPreview v-if="originals" :file="comparison[side]" /><div v-else class="desk-text"><template v-for="(part,i) in fragments(side)" :key="i"><mark v-if="part.index != null" :id="`match-${side}-${part.index}`">{{ part.text }}</mark><span v-else>{{ part.text }}</span></template></div></article></div></template></template>
    <div v-else-if="selected" class="desk-grading"><aside class="desk-students"><input v-model="query" type="search" placeholder="姓名 / 学号" aria-label="搜索报告学生"><select v-model="filter" aria-label="筛选批阅状态"><option value="all">全部状态</option><option>待批改</option><option>批改中</option><option>已批改</option><option>已退回</option></select><div class="desk-student-list"><button v-for="r in filtered" :key="r.runId + r.sid" :class="{active: r.runId === active.runId && r.sid === active.sid}" :disabled="busy || !r.latest" @click="perform(() => open(r))"><b>{{ r.name }}</b><span>{{ status(r.latest) }}</span><small>{{ r.sid }} · {{ r.groupName }}</small><small>{{ stamp(r.latest?.submittedAt) }}</small><small>成绩 {{ r.latest?.finalScore ?? '—' }}</small></button></div></aside><article class="desk-document"><header><h3>{{ active.name }} · 实验报告</h3><div class="wf-actions"><button class="wf-text-button" @click="perform(() => downloadFile(selected.fileId,selected.fileName))">原始报告</button><button v-if="selected.finalScore != null" class="wf-text-button" @click="perform(gradedFile)">下载批阅记录</button><button class="wf-text-button" :disabled="busy" @click="perform(check, '查重完成')">查重对比</button></div></header><ReportPreview :file="selected" /></article><aside class="desk-assessment"><ReportReview :report="selected" :busy="busy" :ai-loading="aiLoading" :mode="mode" @update:mode="mode = $event" @ai="perform(generateAi, 'AI 批阅完成')" @similarity="perform(check, '查重完成')" @grade="v => perform(() => review('grade',v), '最终成绩已保存')" @return="v => perform(() => review('return',v), '报告已退回')" /></aside></div>
  </section>
</template>
<style scoped>
.desk-modal{position:fixed;inset:0;background:#14263066;z-index:1000;display:grid;place-items:center}.desk-modal form{padding:28px;border-radius:8px;background:white;width:min(460px,90vw)}.desk-modal label{display:grid;gap:8px;margin:20px 0}.report-desk{background:#fff;border:1px solid #dfe7eb;border-radius:8px;padding:20px;min-width:0}.desk-head,.desk-tools{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:20px}.desk-head h2{font-size:20px;margin:0}.desk-tools{justify-content:flex-start}.desk-tools>span{margin-left:auto}.desk-table{overflow:auto}.desk-table table{width:100%;border-collapse:collapse;min-width:1180px;font-size:13px}.desk-table th{background:#f7f9fb;text-align:left;white-space:nowrap}.desk-table th,.desk-table td{padding:16px 12px;border-bottom:1px solid #e8edf0}.desk-table small{display:block;color:#71818d;margin-top:5px}.desk-table .btn{font-size:12px;white-space:nowrap;padding:7px 10px}.desk-row-actions{min-width:240px;margin:0}.desk-status{white-space:nowrap;background:#fff1df;color:#9b6326;border-radius:4px;padding:5px 8px}.desk-status.done{background:#e4f4ed;color:#247457}.desk-grading{display:grid;grid-template-columns:190px minmax(0,1fr) 320px;gap:16px;height:clamp(540px,calc(100dvh - 330px),820px);min-height:0;align-items:stretch}.desk-students{display:flex;min-height:0;flex-direction:column;overflow:hidden}.desk-students>input,.desk-students>select{flex:0 0 auto;width:100%;margin-bottom:12px}.desk-student-list{min-height:0;flex:1;overflow-y:auto;padding-right:5px;scrollbar-gutter:stable}.desk-student-list::-webkit-scrollbar{width:7px}.desk-student-list::-webkit-scrollbar-thumb{border-radius:8px;background:#bdcbd0}.desk-student-list>button{display:block;width:100%;padding:14px;text-align:left;border:1px solid #dfe7eb;background:#fff;margin-bottom:10px;border-radius:6px;color:#304956;cursor:pointer}.desk-student-list>button.active{background:#edf7f7;border-color:#087c88}.desk-students small{display:block;margin-top:8px}.desk-students span{float:right;font-size:12px}.desk-document{display:flex;min-width:0;min-height:0;flex-direction:column;overflow:hidden;border:1px solid #dfe7eb}.desk-document header{flex:0 0 auto;padding:16px;display:flex;gap:12px;flex-wrap:wrap;align-items:center}.desk-document h3{margin:0;font-size:16px}.desk-document :deep(.report-preview){flex:1;min-height:0;height:100%;overflow:hidden}.desk-document :deep(.report-preview iframe){height:100%;min-height:0}.desk-document :deep(.report-preview__empty){height:100%;min-height:0}.desk-assessment{min-width:0;min-height:0;overflow:hidden}.desk-assessment :deep(.report-review){margin:0}.desk-assessment :deep(.review-block){padding:14px}.desk-assessment :deep(.review-block header){flex-wrap:wrap}.desk-assessment :deep(h3){font-size:16px}.desk-assessment :deep(.btn){font-size:12px}.desk-segments{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px;margin:20px 0}.desk-segments button{display:grid;text-align:left;border:1px solid #dfe7eb;border-left:5px solid #efcf66;border-radius:5px;background:white;padding:12px;gap:8px;cursor:pointer}.desk-segments span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.desk-compare{display:grid;grid-template-columns:1fr 1fr;gap:24px}.desk-compare article{min-width:0}.desk-text{white-space:pre-wrap;line-height:2.1;padding:28px;background:#fff;border:1px solid #dfe7eb;height:65vh;overflow:auto;margin-top:16px;overflow-wrap:anywhere}.desk-text mark{background:#fff0a7;scroll-margin:80px}.desk-error{padding:16px;border:1px solid #d89c94;color:#a53a30;margin-bottom:16px}.desk-error button{float:right}@media(min-width:1500px){.desk-grading{grid-template-columns:210px minmax(0,1fr) 350px}}@media(max-width:1200px){.desk-grading{grid-template-columns:170px minmax(0,1fr);height:auto;min-height:620px}.desk-assessment{grid-column:2;height:620px}.desk-document{height:620px}.desk-students{max-height:620px}}@media(max-width:700px){.desk-grading,.desk-compare{grid-template-columns:1fr;min-height:0}.desk-assessment{grid-column:auto;height:auto;overflow:visible}.desk-document{height:560px}.desk-students{max-height:250px}.report-desk{padding:12px}}
</style>
